CREATE TABLE job_version_compatibility (job_id TEXT NOT NULL, project_id TEXT NOT NULL, scene_id TEXT NOT NULL, version_id TEXT NOT NULL, compatible_with_id TEXT NOT NULL, PRIMARY KEY(job_id,version_id), FOREIGN KEY(job_id,project_id) REFERENCES jobs(id,project_id) ON DELETE RESTRICT, FOREIGN KEY(version_id,scene_id,project_id) REFERENCES scene_versions(id,scene_id,project_id) ON DELETE RESTRICT, FOREIGN KEY(compatible_with_id,scene_id,project_id) REFERENCES scene_versions(id,scene_id,project_id) ON DELETE RESTRICT);
